function buildCues(texts: string[]): CaptionCue[] {
  return texts.map((text, idx) => {
    const time = timestamps[idx] || { start: idx * 4, duration: 3.5 };
    const words = text.split(' ');
    const segs = words.map((w, wIdx) => ({
      utf8: w + (wIdx < words.length - 1 ? ' ' : ''),
      tOffsetMs: Math.round((wIdx / Math.max(1, words.length)) * time.duration * 1000),
    }));
    return {
      id: `n9-cue-${idx + 1}`,
      start: time.start,
      duration: time.duration,
      text,
      segs,
    };
  });
}

export const N9QWEO5QSOO_LANGUAGE_TRACKS: Record<string, CaptionCue[]> = {
  en: buildCues(enTexts),
  es: buildCues(esTexts),
  he: buildCues(heTexts),
  iw: buildCues(heTexts),
  il: buildCues(heTexts),
  it: buildCues(itTexts),
  ar: buildCues(arTexts),
  ru: buildCues(ruTexts),
};
